// POST /functions/v1/create-order        Body: { productId, useWallet?: boolean }
// Header: Authorization: Bearer <user access token>   (verify_jwt = true)
//
// The ONLY way an order comes into existence. The client sends a product id and
// an optional "use my referral balance" flag, never an amount. The database
// (create_priced_order) reads the price from `products`, applies the friend's
// first-purchase discount and the wallet (eligible product types and max share) from
// referral_settings and the ledger, and stores list price + discount + wallet +
// final amount on the order. The Razorpay order is then created for exactly
// that final amount. The row is immutable afterwards (orders_01_immutable_columns)
// and clients have no write access to `orders`, so "pay Rs 49, then switch the
// order to Rs 1,999" - or "claim a bigger discount" - is impossible.
import { handleOptions, jsonResponse } from "../_shared/cors.ts";
import { supabaseAdmin, getUserFromAuthHeader } from "../_shared/supabaseAdmin.ts";
import { createRazorpayOrder, getRazorpayKeyId, isLiveMode } from "../_shared/razorpay.ts";
import { withinLimit } from "../_shared/rateLimit.ts";

Deno.serve(async (req: Request) => {
  const preflight = handleOptions(req);
  if (preflight) return preflight;
  if (req.method !== "POST") return jsonResponse({ error: "Method not allowed." }, 405);

  try {
    const user = await getUserFromAuthHeader(req);
    if (!user) return jsonResponse({ error: "Please log in before purchasing." }, 401);

    const body = (await req.json().catch(() => ({}))) as { productId?: unknown; useWallet?: unknown };
    const productId = typeof body.productId === "string" ? body.productId : "";
    const useWallet = body.useWallet === true; // anything else = false; no amounts are ever read from the body
    if (!productId || productId.length > 100) return jsonResponse({ error: "Missing productId." }, 400);

    if (!(await withinLimit(`create-order:${user.id}`, 10, 600))) {
      return jsonResponse({ error: "Too many attempts. Please wait a few minutes and try again." }, 429);
    }

    const { data: profile } = await supabaseAdmin
      .from("profiles")
      .select("name, email, course_id, blocked")
      .eq("id", user.id)
      .maybeSingle();
    if (!profile || profile.blocked) return jsonResponse({ error: "This account cannot make purchases." }, 403);
    if (!profile.course_id) return jsonResponse({ error: "Please select your course before purchasing." }, 400);

    // Only the course check lives here; price, scope, discount and wallet are
    // all decided inside create_priced_order().
    const { data: product } = await supabaseAdmin
      .from("products")
      .select("id, course_id, active")
      .eq("id", productId)
      .maybeSingle();
    if (!product || !product.active) {
      return jsonResponse({ error: "This product is no longer available." }, 400);
    }
    if (profile.course_id !== product.course_id) {
      return jsonResponse({ error: "This product isn't available for your course." }, 403);
    }

    const { data: priced, error: pricedErr } = await supabaseAdmin.rpc("create_priced_order", {
      p_user_id: user.id,
      p_product_id: product.id,
      p_use_wallet: useWallet,
    });
    if (pricedErr || !priced) {
      console.error("create-order: create_priced_order failed", pricedErr?.code, pricedErr?.message);
      return jsonResponse({ error: "Something went wrong. Please try again." }, 500);
    }
    if (!priced.ok) {
      const messages: Record<string, string> = {
        product_unavailable: "This product is no longer available.",
        wallet_not_allowed: "Referral balance can only be used on notes purchases.",
        invalid_price: "This product doesn't have a valid price.",
        already_owned: "You already own this. It is in your library.",
      };
      return jsonResponse({ error: messages[priced.code] ?? "This order could not be created." }, 400);
    }

    const orderId: string = priced.order_id; // uuid, <= 40 chars, valid Razorpay receipt
    const amountPaise = Math.round(Number(priced.amount) * 100);
    if (!Number.isSafeInteger(amountPaise) || amountPaise < 100) {
      await supabaseAdmin.from("orders").update({ status: "failed" }).eq("id", orderId);
      return jsonResponse({ error: "This product doesn't have a valid price." }, 400);
    }

    let razorpayOrder: { id: string };
    try {
      razorpayOrder = await createRazorpayOrder({
        amountPaise,
        receipt: orderId,
        notes: { uid: user.id, productId: product.id, orderId },
      });
    } catch (err) {
      console.error("create-order: Razorpay order creation failed", err);
      // Release any wallet hold / discount reserved for this attempt.
      await supabaseAdmin.from("orders").update({ status: "failed" }).eq("id", orderId);
      return jsonResponse({ error: "Could not start the payment. Please try again." }, 502);
    }

    // One-time NULL -> value (the immutability trigger allows exactly this).
    const { error: attachErr } = await supabaseAdmin
      .from("orders")
      .update({ razorpay_order_id: razorpayOrder.id })
      .eq("id", orderId)
      .is("razorpay_order_id", null);
    if (attachErr) {
      console.error("create-order: attach razorpay id failed", attachErr.code, attachErr.message);
      await supabaseAdmin.from("orders").update({ status: "failed" }).eq("id", orderId);
      return jsonResponse({ error: "Something went wrong. Please try again." }, 500);
    }

    return jsonResponse({
      keyId: getRazorpayKeyId(),
      isLiveMode: isLiveMode(),
      razorpayOrderId: razorpayOrder.id,
      amountPaise,
      productTitle: priced.title,
      internalOrderId: orderId,
      // Display only: the amount actually charged is amountPaise, decided above.
      breakdown: {
        listPrice: Number(priced.list_price),
        referralDiscount: Number(priced.referral_discount),
        walletAmount: Number(priced.wallet_amount),
        amount: Number(priced.amount),
      },
      // Checkout is told to stop accepting payment when the order expires. Razorpay
      // orders themselves cannot expire, so the database enforces it at settlement.
      timeoutSeconds: Number(priced.timeout_seconds) || 1800,
      verifyUrl: `${Deno.env.get("SUPABASE_URL")}/functions/v1/verify-payment`,
      prefillName: profile.name ?? "",
      prefillEmail: profile.email ?? "",
    });
  } catch (err) {
    console.error("create-order: unhandled error", err);
    return jsonResponse({ error: "Something went wrong. Please try again." }, 500);
  }
});

// supabase/functions/_shared/cors.ts

export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

export function handleOptions(req: Request): Response | null {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  return null;
}

// JSON response helper. "pay" and "verify-payment" used to return HTML
// pages meant for an external browser - Supabase doesn't serve real
// text/html on the default *.supabase.co domain (scripts get sandboxed
// and blocked), which is why the checkout button did nothing. They now
// return JSON, and the checkout UI runs inside the app's own WebView.
export function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

import { createClient } from "npm:@supabase/supabase-js@2";

// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are injected automatically
// into every Edge Function's environment - no need to set them manually
// via `supabase secrets set`. The service role key bypasses RLS, which
// this backend needs: it has to read/write orders, purchases, and
// payment_sessions across users, not just the calling user's own rows.
const supabaseUrl = Deno.env.get("SUPABASE_URL");
const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

if (!supabaseUrl || !serviceRoleKey) {
  throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY Edge Function environment variable.");
}

export const supabaseAdmin = createClient(supabaseUrl, serviceRoleKey, {
  auth: { persistSession: false, autoRefreshToken: false },
});

// Verifies the bearer token from an incoming request's Authorization
// header and returns the authenticated user - the only thing that should
// ever identify who's paying. Never trust a uid passed as a plain body/
// query param, since that would let anyone buy a product "as" someone
// else.
export async function getUserFromAuthHeader(
  req: Request
): Promise<{ id: string; email?: string } | null> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "");
  if (!token) return null;

  const { data, error } = await supabaseAdmin.auth.getUser(token);
  if (error || !data.user) return null;

  return { id: data.user.id, email: data.user.email ?? undefined };
}

// The session's authentication assurance level ("aal1" = password only, "aal2" = MFA done).
// Only call this AFTER getUserFromAuthHeader() accepted the same token: it decodes the payload
// without re-verifying the signature.
export function aalFromAuthHeader(req: Request): string {
  const token = (req.headers.get("Authorization") ?? "").replace(/^Bearer\s+/i, "");
  try {
    const b64 = token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
    const claims = JSON.parse(atob(b64.padEnd(Math.ceil(b64.length / 4) * 4, "=")));
    return typeof claims.aal === "string" ? claims.aal : "";
  } catch {
    return "";
  }
}

// Talks to Razorpay's REST API directly over fetch (rather than importing
// the `razorpay` npm package) - keeps this dependency-free, which matters
// more in a Deno Edge Function than it did in the old Node/Firebase
// backend, where npm packages were the natural choice.

// Every call to Razorpay is bounded so a stalled connection fails fast (create-order answers 502,
// the webhook answers 5xx and Razorpay retries) instead of hanging until the platform kills the function.
const RAZORPAY_TIMEOUT_MS = 15_000;

function getKeys(): { keyId: string; keySecret: string } {
  const keyId = Deno.env.get("RAZORPAY_KEY_ID");
  const keySecret = Deno.env.get("RAZORPAY_KEY_SECRET");

  if (!keyId || !keySecret) {
    throw new Error(
      "Razorpay keys are not configured. Run:\n" +
        "  supabase secrets set RAZORPAY_KEY_ID=...\n" +
        "  supabase secrets set RAZORPAY_KEY_SECRET=..."
    );
  }

  // SAFETY CHECK: a previous incident had a real rzp_test_ key committed
  // to the repo (see SECURITY_NOTICE.md) and silently deployed as this
  // function's production secret - a console.warn() alone was too easy to
  // miss in logs nobody was watching, and every order kept getting created
  // as a Razorpay TEST order, which real UPI apps (PhonePe/GPay) do not
  // handle the same way as a live order (unreliable callbacks, different
  // auto-capture timing) - this was the actual root cause of intermittent
  // "payment succeeded but verification could not be confirmed" reports.
  //
  // Test mode is still fine for staging - but it now requires a conscious,
  // explicit opt-in secret (ALLOW_TEST_MODE=true) rather than being the
  // silent default the moment a test key ends up deployed. Without that
  // opt-in, a test key hard-fails every request instead of quietly
  // accepting real student payments against a test-mode order.
  if (keyId.startsWith("rzp_test_")) {
    const allowTestMode = Deno.env.get("ALLOW_TEST_MODE") === "true";
    if (!allowTestMode) {
      throw new Error(
        "Refusing to run with a rzp_test_ Razorpay key: ALLOW_TEST_MODE is not set to 'true'. " +
          "If this is staging and test mode is intentional, run " +
          "`supabase secrets set ALLOW_TEST_MODE=true`. " +
          "If this is production, you have the wrong key deployed - run " +
          "`supabase secrets set RAZORPAY_KEY_ID=rzp_live_...` and " +
          "`supabase secrets set RAZORPAY_KEY_SECRET=...` with your LIVE keys from " +
          "the Razorpay Dashboard (Settings -> API Keys, Live mode toggle)."
      );
    }
    console.warn(
      "[razorpay] RUNNING IN TEST MODE (RAZORPAY_KEY_ID starts with rzp_test_, " +
        "ALLOW_TEST_MODE=true). Real payments will NOT be processed."
    );
  }

  return { keyId, keySecret };
}

// Lets callers (e.g. `pay`) tell the client which mode it's in, so the app
// can visibly label the checkout screen "TEST MODE" instead of a student
// silently paying (or trying to pay) against a non-live order.
export function isLiveMode(): boolean {
  return getKeys().keyId.startsWith("rzp_live_");
}

export function getRazorpayKeyId(): string {
  return getKeys().keyId;
}

export async function createRazorpayOrder(params: {
  amountPaise: number;
  receipt: string;
  notes?: Record<string, string>;
}): Promise<{ id: string }> {
  const { keyId, keySecret } = getKeys();

  const res = await fetch("https://api.razorpay.com/v1/orders", {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Basic " + btoa(`${keyId}:${keySecret}`),
    },
    body: JSON.stringify({
      amount: params.amountPaise,
      currency: "INR",
      receipt: params.receipt,
      notes: params.notes ?? {},
    }),
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay order creation failed (${res.status}): ${body}`);
  }

  return (await res.json()) as { id: string };
}

// Server-to-server, authoritative check: asks Razorpay directly whether an
// order has a captured payment, using our own secret key. Used for
// "recovery" - e.g. when the app's WebView never got to relay Checkout's
// success callback (Android killed the WebView's renderer process while
// the app was backgrounded for a UPI app switch) even though the payment
// itself went through fine on Razorpay's side. Doesn't need a client-
// supplied signature at all, since this is us asking Razorpay ourselves.
export async function fetchCapturedPaymentForOrder(
  razorpayOrderId: string
): Promise<{ id: string; amount: number } | null> {
  const { keyId, keySecret } = getKeys();

  const res = await fetch(`https://api.razorpay.com/v1/orders/${razorpayOrderId}/payments`, {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay order-payments lookup failed (${res.status}): ${body}`);
  }

  const data = (await res.json()) as { items: { id: string; status: string; amount: number }[] };
  const captured = data.items.find((p) => p.status === "captured");
  return captured ? { id: captured.id, amount: captured.amount } : null;
}


export type RazorpayPayment = {
  id: string;
  order_id: string | null;
  status: string;
  amount: number;
  currency: string;
  captured?: boolean;
  created_at?: number; // epoch seconds: when the customer started this payment
  amount_refunded?: number;
  refund_status?: string | null; // "partial" | "full" | null
};

async function razorpayGet<T>(path: string): Promise<T> {
  const { keyId, keySecret } = getKeys();
  const res = await fetch(`https://api.razorpay.com/v1/${path}`, {
    signal: AbortSignal.timeout(RAZORPAY_TIMEOUT_MS),
    headers: { Authorization: "Basic " + btoa(`${keyId}:${keySecret}`) },
  });
  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`Razorpay GET ${path.split("/")[0]} failed (${res.status}): ${body}`);
  }
  return (await res.json()) as T;
}

// Authoritative, server-to-server fetch of a single payment.
export function fetchPayment(paymentId: string): Promise<RazorpayPayment> {
  return razorpayGet<RazorpayPayment>(`payments/${encodeURIComponent(paymentId)}`);
}

export type RazorpayDispute = {
  id: string;
  payment_id: string;
  status: string; // "open" | "under_review" | "won" | "lost" | "closed"
  phase?: string; // "chargeback" | "fraud" | ...
  amount?: number;
};

// Authoritative, server-to-server fetch of a single dispute (chargeback).
export function fetchDispute(disputeId: string): Promise<RazorpayDispute> {
  return razorpayGet<RazorpayDispute>(`disputes/${encodeURIComponent(disputeId)}`);
}

export function fetchRazorpayOrder(
  razorpayOrderId: string
): Promise<{ id: string; amount: number; currency: string; status: string }> {
  return razorpayGet(`orders/${encodeURIComponent(razorpayOrderId)}`);
}

function hexToBytes(hex: string): Uint8Array | null {
  if (!/^[0-9a-f]{64}$/i.test(hex)) return null;
  const out = new Uint8Array(32);
  for (let i = 0; i < 32; i++) out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

// signature = HMAC_SHA256(razorpay_order_id + "|" + razorpay_payment_id, KEY_SECRET)
// Must match exactly what Checkout.js sends back. Compared in constant time
// over the decoded 32-byte digests (no early exit on the first differing byte).
export async function verifyPaymentSignature(params: {
  razorpayOrderId: string;
  razorpayPaymentId: string;
  razorpaySignature: string;
}): Promise<boolean> {
  const { keySecret } = getKeys();

  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    enc.encode(keySecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const expected = new Uint8Array(
    await crypto.subtle.sign("HMAC", key, enc.encode(`${params.razorpayOrderId}|${params.razorpayPaymentId}`))
  );
  const actual = hexToBytes(params.razorpaySignature);
  if (!actual) return false;

  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= expected[i] ^ actual[i];
  return diff === 0;
}

import { supabaseAdmin } from "./supabaseAdmin.ts";

export async function sha256Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export function clientIp(req: Request): string {
  const forwarded = req.headers.get("cf-connecting-ip")
    ?? req.headers.get("x-real-ip")
    ?? req.headers.get("x-forwarded-for")?.split(",")[0]
    ?? "unknown";
  return forwarded.trim() || "unknown";
}

// true = within limit. By default fails OPEN on a database error (availability of the
// endpoint; the auth provider's own limits still apply behind it). Pass failClosed for
// brute-force-sensitive endpoints (password login) where "limiter down" must not mean
// "no limit".
export async function withinLimit(
  key: string,
  limit: number,
  windowSeconds: number,
  failClosed = false,
): Promise<boolean> {
  const { data, error } = await supabaseAdmin.rpc("rate_limit_hit", {
    p_key: await sha256Hex(key),
    p_limit: limit,
    p_window_seconds: windowSeconds,
  });
  if (error) {
    console.error("rateLimit: rpc failed", error.code);
    return !failClosed;
  }
  return data === true;
}
